import {EVENTS,GROUPS,RANKS,SCHOOLS,LESSONS,seed,selectEvent,completeLesson,createAssignment,assignmentsFor,postsFor,addPost,progress} from './model.js';
import {backgroundPaths,initLanding} from './landing.js';
import {glassArt} from './art.js';

const app=document.querySelector('#app'), modal=document.querySelector('#modal');
let state;
try {state=JSON.parse(localStorage.getItem('halus-state'));} catch {}
if(!state||state.version!==1)state=seed();
let currentTab='Knowledge',assignmentFilter='All',rankScope='Global',eventFilter='All',eventSearch='',studentSearch='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem('halus-state',JSON.stringify(state));}catch{toast('Storage is unavailable. Changes will last for this session only.');}};
const school=()=>SCHOOLS[state.school];
const event=()=>EVENTS.find(e=>e.name===state.event);
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const icon=(name,cls='')=>'<svg class="icon '+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+({
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11Z"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 1 3-1 5-2 9-1v15c-4-1-6 0-9 1-3-1-5-2-9-1Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',check:'<path d="m5 12 4 4L19 6"/>',list:'<path d="M9 6h11M9 12h11M9 18h11M3 6h1M3 12h1M3 18h1"/>',chart:'<path d="M4 3v17h17M8 15V9m5 6V5m5 10v-5"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4c3 0 4 3 4 5v2"/>',trophy:'<path d="M7 3h10v5c0 7-10 7-10 0V3Zm0 2H3v3c0 3 3 4 5 4m9-7h4v3c0 3-3 4-5 4m-4 2v6m-4 1h8"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',logout:'<path d="M9 4H4v16h5m4-8h8m-4-4 4 4-4 4"/>',message:'<path d="M4 4h16v12H9l-5 4V4Z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',leaf:'<path d="M5 20C-1 7 9 2 21 3c0 13-6 18-13 15M5 20 16 9"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>'
}[name]||'<circle cx="12" cy="12" r="8"/>')+'</svg>';
const mark=()=>'<img src="assets/symbol.svg" alt="" class="brand-mark">';
const wordmark=()=>'<svg class="wordmark" viewBox="0 0 130 36" aria-label="halus" role="img"><g fill="none" stroke="currentColor" stroke-width="4.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5v25m0-13h11q5 0 5 5v8M46 30H33q-6 0-6-6t6-6h13v12M54 5v19q0 6 6 6h4M72 18v6q0 6 6 6h10V18M117 18h-15q-5 0-5 3t5 3h10q5 0 5 3t-5 3H97"/></g></svg>';
const logo=()=>'<a class="brand" href="#/" aria-label="Halus home">'+mark()+wordmark()+'</a>';
const themeButton=()=>'<button class="icon-button theme-toggle" data-action="theme" aria-label="Switch to '+(document.documentElement.dataset.theme==='dark'?'light':'dark')+' mode">'+icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')+'</button>';
const button=(label,action,extra='',secondary=false)=>'<button class="button '+(secondary?'secondary':'')+'" data-action="'+action+'" '+extra+'>'+label+'</button>';
const linkButton=(label,href,secondary=false)=>'<a class="button '+(secondary?'secondary':'')+'" href="'+href+'">'+label+'<span class="button-tail">'+icon('arrow')+'</span></a>';
const hal=(cls='')=>'<img class="hal '+cls+'" src="assets/hal.png" alt="Hal, a friendly red pixel snake resting in a coil">';
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3800);}
function showModal(title,body){modal.innerHTML='<div class="modal-head"><h2 id="modal-title">'+title+'</h2><button class="icon-button" data-action="close" aria-label="Close dialog">'+icon('close')+'</button></div>'+body;modal.showModal();}
function footer(){return '<footer class="footer">'+logo()+'<div class="footer-links"><a href="#/mission">About</a><i>·</i><a href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">HOSA guidelines ↗</a><i>·</i><span>Independent study platform</span><i>·</i><button class="text-button" data-action="about">Preview notes</button></div><span class="footer-tag spaced"><b>+</b>SAME STUDENTS<br>BRIGHTER TOMORROW</span><small>Independent learning project. Not affiliated with HOSA–Future Health Professionals.</small></footer>';}
const ORBIT=[
 {title:'Health Science',tag:'Written knowledge',body:'Deep, test-based events like Medical Terminology and Pharmacology. Build recall one system at a time.',ico:'book'},
 {title:'Health Professions',tag:'Test + skills',body:'Clinical events like Nursing Assisting and Sports Medicine pair a written test with hands-on skill stations.',ico:'check'},
 {title:'Emergency Preparedness',tag:'Scenarios',body:'CPR/First Aid, EMT, and Public Health — practise calm, accurate steps when it counts.',ico:'spark'},
 {title:'Leadership',tag:'Speaking & writing',body:'Interviews, prepared speeches, and health policy writing. Find your voice and refine it.',ico:'message'},
 {title:'Teamwork',tag:'Team events',body:'HOSA Bowl, Biomedical Debate, and Medical Innovation — prepare together as a team.',ico:'users'}];
function siteHeader(active=''){const nav=[['Home','#/','home'],['What is Halus?','#/mission','mission'],['Global rankings','#/leaderboard','rankings']];return '<header class="site-header landing-header">'+logo()+'<nav class="glass-nav" aria-label="Main navigation"><span class="nav-pill" aria-hidden="true"></span>'+nav.map(([l,h,k])=>'<a href="'+h+'" class="'+(k===active?'current':'')+'" '+(k===active?'aria-current="page"':'')+'>'+l+'</a>').join('')+'</nav><div class="header-actions">'+themeButton()+'<a class="button secondary login" href="#/student">'+icon('book')+'<span>Student<span class="login-word"> login</span></span></a><a class="button login" href="#/teacher">'+icon('users')+'<span>Instructor<span class="login-word"> login</span></span></a></div></header>';}
const MOVES=[
 {name:'Medical Terminology',line:'BUILD A STRONGER<br>FOUNDATION',art:'stethoscope',pos:'10% 30%'},
 {name:'Nursing Assisting',line:'REAL SKILLS<br>REAL IMPACT',art:'heart',pos:'70% 40%'},
 {name:'Pharmacology',line:'KNOW EVERY<br>PRESCRIPTION',art:'capsule',pos:'40% 70%'},
 {name:'Biotechnology',line:'SCIENCE THAT<br>SHAPES CARE',art:'dna',pos:'90% 20%'},
 {name:'Phlebotomy',line:'STEADY HANDS<br>CLEAR STEPS',art:'drop',pos:'30% 90%'},
 {name:'CPR/First Aid',line:'CALM WHEN<br>IT COUNTS',art:'cross',pos:'60% 10%'}];
function studyPanel(){const tabs=['Study','Practice','Progress','Chapter'];
 const link=(ico,t)=>'<a href="#/start">'+icon(ico)+'<span>'+t+'</span></a>';
 const pane=(k,mid,right)=>'<div class="sp-pane'+(k==='Study'?' active':'')+'" data-pane="'+k+'"><div class="sp-mid">'+mid+'</div><div class="sp-right">'+right+'</div></div>';
 return '<section class="study-panel glass-card" id="about" data-reveal><h2 class="tech">a space that <em>grows with you.</em></h2><div class="sp-tabs" role="tablist"><span class="sp-pill" aria-hidden="true"></span>'+tabs.map((t,i)=>'<button role="tab" data-tab="'+t+'" class="'+(i?'':'active')+'" aria-selected="'+!i+'">'+t+'</button>').join('')+'</div>'+
 '<div class="sp-body"><div class="sp-left"><span class="micro">SECONDARY DIVISION</span><div class="sp-event">Nursing Assisting '+icon('chevron')+'</div><nav>'+link('book','Event guide')+link('list','Resources')+link('chart','Practice questions')+'</nav></div><div class="sp-stage">'+
 pane('Study','<div class="sp-head"><div><span class="micro red">LESSON 2 OF 6</span><h3>Infection control</h3></div><span class="micro">11 MIN</span><span class="play">'+icon('chevron')+'</span></div><ol class="sp-lessons"><li class="on"><i></i><small>01</small>Standard precautions'+icon('chevron')+'</li><li><i></i><small>02</small>Hand hygiene techniques'+icon('chevron')+'</li><li><i></i><small>03</small>Personal protective equipment'+icon('chevron')+'</li></ol>',
  '<div class="glass-ring" style="--val:68"><strong>68<small>%</small></strong><span>COMPLETE</span></div>'+linkButton('Continue lesson','#/start'))+
 pane('Practice','<div class="sp-head"><div><span class="micro red">QUICK CHECK · 3 OF 10</span><h3>Which step comes first?</h3></div></div><ol class="sp-lessons quiz"><li><i></i><small>A</small>Put on gloves</li><li class="on"><i></i><small>B</small>Perform hand hygiene</li><li><i></i><small>C</small>Identify the patient</li></ol>',
  '<div class="glass-ring" style="--val:84"><strong>84<small>%</small></strong><span>ACCURACY</span></div>'+linkButton('Keep practising','#/start'))+
 pane('Progress','<div class="sp-head"><div><span class="micro red">THIS WEEK</span><h3>Small steps, every day.</h3></div></div><div class="sp-bars">'+['M','T','W','T','F','S','S'].map((d,i)=>'<span style="--h:'+[40,55,35,70,62,85,92][i]+'%"><i></i><small>'+d+'</small></span>').join('')+'</div>',
  '<div class="glass-ring" style="--val:92"><strong>92<small>%</small></strong><span>BEST DAY</span></div>'+linkButton('See analytics','#/start'))+
 pane('Chapter','<div class="sp-head"><div><span class="micro red">WESTBRIDGE HIGH · MEMBERS ONLY</span><h3>Around your chapter</h3></div></div><div class="sp-post"><span class="avatar">JR</span><div><strong>Ms. Rivera</strong><p>Skills lab is Thursday at 3:30 in room 204. Bring your event guidelines.</p></div></div>',
  '<div class="sp-lock">'+icon('lock')+'<strong>Private to<br>your school</strong></div>'+linkButton('Visit chapter','#/start'))+
 '</div></div><span class="sp-note micro">ILLUSTRATIVE PREVIEW</span></section>';}
function landing(){
 return siteHeader('home')+'<main id="main" class="landing">'+
 '<section class="hero"><div class="hero-art" aria-hidden="true"></div><div class="aurora" aria-hidden="true"><i></i><i></i><i></i></div><div class="hero-wash"></div>'+lightTrails()+
 '<span class="hud hud-tl" aria-hidden="true">LEARN<br>PRACTICE<br>GROW<br>BELONG</span><span class="hud hud-tr" aria-hidden="true">SAME<br>CURIOSITY<br>BRIGHTER<br>TOMORROW</span>'+
 '<div class="hero-content"><span class="spaced boot b1">A NEW RHYTHM FOR HOSA</span><h1 class="tech boot b2"><span class="line">your future,</span><span class="rotator" aria-live="off"><b class="in">in practice.</b><b>in focus.</b><b>in motion.</b><b>within reach.</b></span></h1><div class="hero-cta boot b3">'+linkButton('Find your place','#/start')+'<a class="ghost-link" href="#/mission">What is Halus? '+icon('chevron')+'</a></div><p class="hero-caption boot b4">One event this year. A study space built around you.</p></div>'+
 '<div class="hero-companion boot b5"><span class="px-spark s1"></span><span class="px-spark s2"></span><span class="px-spark s3"></span><span class="px-spark s4"></span>'+hal()+'<p class="px-bubble" data-typed=\'["let’s find your focus.","one event. one year.","small steps add up."]\'></p></div></section>'+
 studyPanel()+
 '<section class="moves"><div class="moves-head" data-reveal><h2 class="tech">find what <em>moves you.</em></h2><div class="moves-nav"><span class="spaced">SECONDARY DIVISION</span><i class="rule"></i><button class="round-glass" data-move="-1" aria-label="Previous events">'+icon('chevron')+'</button><button class="round-glass" data-move="1" aria-label="Next events">'+icon('chevron')+'</button></div></div>'+
 '<div class="moves-track" data-reveal style="--d:.1s">'+MOVES.map(m=>'<a class="move-card" href="#/events"><span class="move-bg" style="--pos:'+m.pos+'"></span>'+glassArt(m.art)+'<span class="move-text"><strong class="tech">'+m.name+'</strong><small class="spaced">'+m.line+'</small></span><span class="round-glass">'+icon('arrow')+'</span></a>').join('')+'<a class="move-card browse" href="#/events"><span class="plus">+</span><strong>Browse<br>all events</strong><span class="round-glass">'+icon('chevron')+'</span></a></div></section>'+
 '<section class="orbit-section"><div class="orbit-copy" data-reveal><span class="spaced">FIVE WAYS TO COMPETE</span><h2 class="tech">pick one event.<br><em>we’ll shape the rest.</em></h2><p>HOSA’s secondary events fall into five categories, each with its own kind of preparation. Halus adapts your study sections to the one you choose.</p><div class="orbit-detail glass-card"><span class="orbit-tag badge"></span><h3></h3><p></p></div></div>'+
 '<div class="orbit-system" data-reveal style="--d:.15s"><div class="orbit-ring r1"></div><div class="orbit-ring r2"></div><div class="orbit-ring r3"></div><div class="orbit-core"><img src="assets/symbol.svg" alt="" class="core-mark"></div>'+ORBIT.map(o=>'<button class="orbit-node" data-title="'+o.title+'" data-tag="'+o.tag+'" data-body="'+esc(o.body)+'"><span>'+icon(o.ico)+'</span><b>'+o.title+'</b></button>').join('')+'</div></section>'+
 '<section class="chapter-band" id="instructors" data-reveal><div class="band-art" aria-hidden="true"></div><div><h2 class="tech">your chapter.<br><em>your people.</em></h2><p>'+icon('lock')+' A private space to learn together.</p></div><a class="code-pill glass-card" href="#/start">'+icon('lock')+'<span>Join with your school code</span><span class="code-go">'+icon('arrow')+'</span></a><a class="band-teacher" href="#/teacher"><span><strong>For instructors</strong><small class="spaced">SUPPORT YOUR CHAPTER</small></span><span class="round-glass">'+icon('chevron')+'</span></a></section>'+
 '</main>'+footer();}
function lightTrails(){return '<svg class="light-trails" viewBox="0 0 1440 900" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><filter id="trail-glow" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>'+
 [['M-80 760 C 300 520, 900 420, 1520 120',0],['M-60 300 C 400 180, 1000 160, 1500 380',1],['M120 980 C 500 700, 1100 640, 1540 700',2]].map(([d,i])=>'<path d="'+d+'" class="trail-base"/><path d="'+d+'" pathLength="1" class="trail-run t'+i+'" filter="url(#trail-glow)"/>').join('')+'</svg>';}
function navItem(label,href,ico,active){return '<a href="'+href+'" class="'+(active?'active':'')+'" '+(active?'aria-current="page"':'')+'>'+icon(ico)+'<span>'+label+'</span></a>';}
function shell(content,page){const role=state.role,teacher=role==='teacher';return '<div class="workspace"><aside class="sidebar">'+logo()+'<div class="chapter-label"><span class="chapter-avatar">W</span><div><strong>'+school()+'</strong><small>Secondary chapter</small></div></div><nav aria-label="Workspace navigation">'+navItem('Overview',teacher?'#/teacher':'#/student','grid',page==='overview')+(teacher?navItem('Students','#/students','users',page==='students'):navItem('My event','#/my-event','book',page==='event'))+navItem('Assignments','#/assignments','list',page==='assignments')+navItem('Analytics','#/analytics','chart',page==='analytics')+navItem('School community','#/community','message',page==='community')+navItem('Global rankings','#/rankings','trophy',page==='rankings')+'</nav><div class="sidebar-bottom"><div class="hal-card">'+hal()+'<p>Little by little.<br>You’re getting there.</p></div><button class="role-switch" data-action="switch-role">'+icon('users')+'Switch to '+(teacher?'student':'instructor')+'</button><a class="back-home" href="#/">'+icon('logout')+' Back to Halus</a></div></aside><div class="workspace-body"><header class="workspace-top"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">'+icon('menu')+'</button><span class="crumb">Your space <span>/</span> '+(teacher?'Instructor':'Student')+'</span><div class="header-actions"><span class="demo-tag">LOCAL PREVIEW</span>'+themeButton()+'<span class="avatar">'+(teacher?'JR':'MC')+'</span></div></header><main id="main" class="workspace-main">'+content+'</main><footer class="workspace-footer"><span>'+icon('lock')+' '+school()+' · Demo chapter</span><button class="text-button" data-action="about">Browser-local preview · About</button></footer></div></div>';}
function heading(eyebrow,title,subtitle,action=''){return '<div class="page-heading"><div><span class="eyebrow">'+eyebrow+'</span><h1>'+title+'</h1><p>'+subtitle+'</p></div>'+action+'</div>';}
function panelTitle(title,action=''){return '<div class="panel-title"><h2>'+title+'</h2>'+action+'</div>';}
function progressBar(value){return '<div class="progress-track" role="progressbar" aria-valuenow="'+value+'" aria-valuemin="0" aria-valuemax="100" aria-label="Completion"><span style="width:'+value+'%"></span></div>';}
function ring(value){return '<div class="ring" style="--progress:'+value+'"><div><strong>'+value+'<small>%</small></strong><span>COMPLETE</span></div></div>';}
function assignmentRows(role='student',limit=99){const list=assignmentsFor(state,role).filter(a=>assignmentFilter==='All'||(assignmentFilter==='Completed'?a.submitted:!a.submitted)).slice(0,limit);return list.length?'<div class="assignment-list">'+list.map(a=>'<button class="assignment-row" data-action="assignment" data-id="'+a.id+'"><span class="row-icon '+(a.submitted?'done':'')+'">'+icon(a.submitted?'check':'list')+'</span><span><strong>'+esc(a.title)+'</strong><small>'+esc(a.type)+' · '+(role==='teacher'?esc(a.event):'From Ms. Rivera')+'</small></span><span class="row-end"><span class="'+(a.submitted?'status':'due')+'">'+(a.submitted?'Submitted':date(a.due))+'</span>'+icon('chevron')+'</span></button>').join('')+'</div>':'<div class="empty">'+icon('check')+'<h3>All clear for now.</h3><p>No assignments in this view.</p></div>';}
function sparkChart(){const history=state.quizHistory;if(!history.length)return '<div class="chart-empty"><div class="ghost-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p>Your progress starts with your first practice.</p><a class="editorial-link" href="#/my-event">Try a practice check '+icon('arrow')+'</a></div>';return '<div class="history-bars">'+history.slice(-7).map((q,i)=>'<div><span>'+q.score+'%</span><i style="height:'+Math.max(6,q.score)+'px"></i><small>Try '+(i+1)+'</small></div>').join('')+'</div>';}
function overview(){const next=LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0];return heading('YOUR DAILY DOSE OF PROGRESS','Good to see you, Maya.','A little focus today. A little more confidence tomorrow.')+
 '<div class="dashboard-grid"><section class="panel event-hero"><div class="event-heading"><div><span class="eyebrow">'+esc(event()?.category||'YOUR ANNUAL EVENT')+'</span><h2>'+esc(state.event||'Find your event')+'</h2><span class="subtle">'+icon('lock')+' Your event for 2026–27</span></div><a class="round-link" href="#/my-event" aria-label="Open my event">'+icon('arrow')+'</a></div><div class="event-progress"><div><span class="micro">ORIENTATION PATH</span><p>'+state.completed.length+' of '+LESSONS.length+' starter lessons completed</p>'+progressBar(progress(state))+'</div>'+ring(progress(state))+'</div><div class="continue-strip"><div>'+icon('book')+'<span><small>YOUR NEXT STEP</small><strong>'+next.title+'</strong></span></div>'+button('Continue','lesson','data-id="'+next.id+'"')+'</div></section>'+
 '<section class="panel rank-card"><span class="eyebrow">YOUR LEARNING JOURNEY</span><div class="rank-glyph">'+icon('trophy')+'</div><h2>Find your starting point.</h2><p>Ranked assessment is coming next. For now, build your foundations.</p><a class="editorial-link" href="#/rankings">Explore the rank ladder '+icon('arrow')+'</a></section>'+
 '<section class="panel assignments-panel">'+panelTitle('On your list','<a href="#/assignments">View all '+icon('arrow')+'</a>')+assignmentRows('student',3)+'</section><section class="panel progress-panel">'+panelTitle('Your practice')+sparkChart()+'</section>'+
 '<section class="panel chapter-preview">'+panelTitle('Around your chapter','<a href="#/community">Visit chapter '+icon('arrow')+'</a>')+'<div class="notice"><span class="avatar">JR</span><div><strong>Ms. Rivera <span class="badge">INSTRUCTOR</span></strong><p>'+esc(postsFor(state)[0]?.text||'Your chapter feed is ready for its first post.')+'</p></div></div></section></div>';}
function teacherOverview(){return heading('YOUR CHAPTER AT A GLANCE','A little guidance goes a long way.','Make space for the next step in every student’s journey.',button('Create assignment','create-assignment'))+
 '<div class="metric-row"><div><span>Demo chapter</span><strong>4 <small>students</small></strong></div><div><span>Assigned by you</span><strong>'+assignmentsFor(state,'teacher').length+' <small>assignments</small></strong></div><div><span>Submissions ready</span><strong>'+assignmentsFor(state,'teacher').filter(a=>a.submitted).length+' <small>to review</small></strong></div></div>'+
 '<div class="teacher-grid"><section class="panel roster-panel">'+panelTitle('Everyone, in focus','<a href="#/students">View students '+icon('arrow')+'</a>')+roster()+'</section><section class="panel teacher-note"><span class="eyebrow">A MOMENT TO CONNECT</span>'+icon('message')+'<h2>Keep your chapter<br>in the loop.</h2><p>A reminder, a resource, or a little encouragement can go a long way.</p>'+button('Post an announcement','announce','',true)+'</section><section class="panel assignments-panel">'+panelTitle('Chapter assignments','<a href="#/assignments">View all '+icon('arrow')+'</a>')+assignmentRows('teacher',3)+'</section><section class="panel chapter-pulse"><span class="eyebrow">WITH YOU, ALL THE WAY</span><h2>Every small step counts.</h2><p>Support the process, celebrate the progress.</p></section></div>';}
const rosterData=()=>[{name:'Maya Chen',initials:'MC',event:state.event||'Not selected',pct:progress(state),status:'Getting started'}, {name:'Jordan Lee',initials:'JL',event:'Medical Terminology',pct:67,status:'On track'},{name:'Alex Park',initials:'AP',event:'Sports Medicine',pct:33,status:'Check in'},{name:'Sam Patel',initials:'SP',event:'HOSA Bowl',pct:100,status:'On track'}];
function roster(){return '<div class="table-scroll"><table><thead><tr><th>Student</th><th>Annual event</th><th>Orientation</th><th>Status</th></tr></thead><tbody>'+rosterData().filter(s=>(s.name+' '+s.event).toLowerCase().includes(studentSearch.toLowerCase())).map(s=>'<tr><td><div class="student-name"><span class="avatar">'+s.initials+'</span><strong>'+s.name+'</strong></div></td><td>'+esc(s.event)+'</td><td><div class="table-progress">'+progressBar(s.pct)+'<span>'+s.pct+'%</span></div></td><td><span class="status '+(s.status==='Check in'?'attention':'')+'">'+s.status+'</span></td></tr>').join('')+'</tbody></table></div><p class="panel-footnote">Illustrative roster · One active competitive event per student</p>';}
function studentsPage(){return heading('STUDENT DIRECTORY','Know where everyone stands.','View your demo chapter and help students choose their next step.',button('Manage Maya’s event','manage-event','',true))+'<section class="panel"><div class="panel-title"><h2>Your students</h2><label class="search-field">'+icon('search')+'<input id="student-search" type="search" placeholder="Find a student" value="'+esc(studentSearch)+'" aria-label="Find a student"></label></div><div id="roster-result">'+roster()+'</div></section>';}
function assignmentsPage(){return heading('ASSIGNMENTS',state.role==='teacher'?'A clear next step.':'A little structure. A lot of possibility.',state.role==='teacher'?'Create lessons, quizzes, skill checklists, or reflections for an event group.':'Your instructor’s assignments, all in one place.',state.role==='teacher'?button('Create assignment','create-assignment'):'')+'<section class="panel"><div class="filter-tabs" role="group" aria-label="Filter assignments">'+['All','To do','Completed'].map(t=>'<button data-action="filter-assignment" data-value="'+t+'" class="'+(assignmentFilter===t?'selected':'')+'">'+t+'</button>').join('')+'</div>'+assignmentRows(state.role)+'</section>';}
function myEvent(){const category=event()?.category;const sections=category==='Health Science'?['Knowledge','Practice','Notes']:category==='Leadership'||category==='Teamwork'?['Knowledge','Project','Practice','Notes']:['Knowledge','Skills','Practice','Notes'];if(!sections.includes(currentTab))currentTab=sections[0];let body='';
 if(currentTab==='Knowledge')body='<div class="section-intro"><h2>Start with a good foundation.</h2><p>These starter lessons help you plan your preparation. Event-specific medical curriculum is still in development.</p></div><div class="lesson-list">'+LESSONS.map((l,i)=>'<button class="lesson-row" data-action="lesson" data-id="'+l.id+'"><span class="lesson-number">'+(state.completed.includes(l.id)?icon('check'):'0'+(i+1))+'</span><span><small>'+l.tag+'</small><strong>'+l.title+'</strong></span><span class="lesson-time">'+icon('clock')+l.time+'</span>'+icon('arrow')+'</button>').join('')+'</div>';
 if(currentTab==='Skills'||currentTab==='Project')body='<div class="section-intro"><h2>Your preparation checklist.</h2><p>Use this planning checklist alongside the official guidelines and your advisor’s feedback. It is not a clinical competency assessment.</p></div><div class="checklist">'+['Read the current event guidelines','Identify required materials and deadlines','Review the official rating sheets','Schedule a practice with my advisor','Write down feedback and my next step'].map((t,i)=>'<label><input type="checkbox" data-skill="'+i+'" '+(state.skills.includes(i)?'checked':'')+'><span>'+t+'</span></label>').join('')+'</div>';
 if(currentTab==='Practice')body='<div class="practice-intro">'+icon('spark')+'<span class="eyebrow">ORIENTATION CHECK</span><h2>Put your preparation<br>into practice.</h2><p>Three questions about getting ready for your event. This starter check does not affect your rank.</p>'+button('Begin practice','quiz')+'<small>No timer. Room to learn.</small></div>';
 if(currentTab==='Notes')body='<div class="section-intro"><h2>A place for your thoughts.</h2><p>Capture a question, a resource, or something you want to revisit.</p></div><label class="field">My event notebook<textarea id="event-notes" rows="10" placeholder="What do you want to remember?">'+esc(state.notes)+'</textarea></label>'+button('Save notes','save-notes','',true);
 return heading('YOUR EVENT / 2026–27',esc(state.event||'Your event'),'One focus. A study path that grows with you.','<a class="button secondary" href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">Official guidelines ↗</a>')+'<section class="panel event-page"><div class="filter-tabs">'+sections.map(t=>'<button data-action="event-tab" data-value="'+t+'" class="'+(t===currentTab?'selected':'')+'">'+t+'</button>').join('')+'</div><div class="event-page-content">'+body+'</div></section>';}
function analytics(){return heading('YOUR '+(state.role==='teacher'?'CHAPTER’S ':'')+'PROGRESS','See the small steps add up.','Starter learning activity in this local preview.')+'<div class="analytics-grid"><section class="panel">'+panelTitle('Orientation progress')+'<div class="analytics-number">'+ring(progress(state))+'<div><h3>'+state.completed.length+' lessons complete</h3><p>Out of '+LESSONS.length+' starter lessons</p></div></div></section><section class="panel">'+panelTitle('Practice accuracy')+sparkChart()+'</section><section class="panel full-width">'+panelTitle('Recent activity')+(state.quizHistory.length?state.quizHistory.slice().reverse().map(q=>'<div class="activity-row">'+icon('check')+'<strong>Orientation check</strong><span>'+q.score+'% correct</span><small>'+new Date(q.date).toLocaleString('en-US')+'</small></div>').join(''):'<div class="empty"><h3>Your story is just starting.</h3><p>Complete a practice check to see your activity here.</p></div>')+'</section></div>';}
function community(){return heading('YOUR SCHOOL COMMUNITY','A place to grow together.','Demo chapter · '+school()+'. Real school authentication is not connected yet.',button('Change demo chapter','change-school','',true))+'<div class="community-grid"><section><form id="post-form" class="panel composer"><label for="post-text">What’s on your mind?</label><textarea id="post-text" name="text" maxlength="1500" required rows="3" placeholder="'+(state.role==='teacher'?'Share an announcement with your chapter…':'Ask a question or share a small win…')+'"></textarea><div><small>'+icon('lock')+' '+school()+' demo feed</small><button class="button" type="submit">Post to chapter</button></div></form><div class="posts">'+postsFor(state).map(p=>'<article class="panel post"><div class="post-head"><span class="avatar">'+p.author.split(' ').map(n=>n[0]).slice(0,2).join('')+'</span><div><strong>'+esc(p.author)+'</strong><small>'+p.role+' · '+new Date(p.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})+'</small></div></div><p>'+esc(p.text)+'</p></article>').join('')+'</div></section><aside class="panel community-aside"><h2>A little kindness<br>goes a long way.</h2><p>Be curious. Be encouraging. Keep the conversation respectful and focused on learning.</p><div class="divider"></div><span class="eyebrow">YOUR CHAPTER</span><h3>'+school()+'</h3><p>Posts stay in this browser’s demo chapter. Server-enforced privacy will be added with accounts.</p></aside></div>';}
function rankings(){const rows=rankScope==='Global'?[['pulse.exe','Radiant','9,820'],['mintmed','Immortal III','8,460'],['cellmate','Ascendant II','7,240'],['synapse','Diamond I','6,130']]:[['chapterlead','Diamond I','6,130'],['mednotes','Platinum II','4,760'],['studyloop','Gold III','3,980']];return heading('GLOBAL RANKINGS','Find your next level.','A little friendly competition. A shared love of learning.')+'<div class="ranking-layout"><section class="panel"><div class="panel-title"><h2>The leaderboard</h2><span class="badge">ILLUSTRATIVE DATA</span></div><div class="filter-tabs">'+['Global','School'].map(t=>'<button class="'+(t===rankScope?'selected':'')+'" data-action="rank-scope" data-value="'+t+'">'+t+'</button>').join('')+'</div><table class="rank-table"><thead><tr><th>Place</th><th>Student alias</th><th>Rank</th><th>Points</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr><td>0'+(i+1)+'</td><td><strong>'+r[0]+'</strong></td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>').join('')+'</tbody></table><div class="rank-you"><span>You</span><strong>Unranked</strong><small>Ranked assessments are not live yet.</small></div></section><aside class="panel rank-explainer">'+icon('trophy')+'<h2>Mastery comes first.</h2><p>Halus’s proposed ranks follow your growth. Ranked scoring and fair comparisons between events will be added after the assessment system is ready.</p><p>Orientation lessons and repeated practice do not award ranking points.</p></aside><section class="panel full-width">'+panelTitle('The path ahead')+'<div class="rank-ladder">'+RANKS.map((r,i)=>'<div><span class="rank-diamond" style="--rank-hue:'+(i*32)+'">'+icon('spark')+'</span><strong>'+r+'</strong><small>'+(i===8?'TOP RANK':'I · II · III')+'</small></div>').join('')+'</div></section></div>';}
function eventCards(){return EVENTS.filter(e=>(eventFilter==='All'||e.category===eventFilter)&&e.name.toLowerCase().includes(eventSearch.toLowerCase())).map(e=>'<article class="event-card"><span class="micro">'+e.category+'</span><h3>'+e.name+'</h3>'+(e.special?'<span class="badge">IDEA eligibility applies</span>':'<span class="subtle">Secondary division</span>')+'<div><button class="text-button" data-action="event-detail" data-event="'+esc(e.name)+'">View event '+icon('arrow')+'</button></div></article>').join('')||'<div class="empty"><h3>No matching events.</h3><p>Try another search or category.</p></div>';}
function eventsPage(){return siteHeader()+'<main id="main" class="catalog">'+heading('FIND YOUR FOCUS','There’s a place for your curiosity.','Explore the 2026–27 regular competitive events listed for the secondary division. Choose one annual focus in Halus.')+'<div class="catalog-toolbar"><label class="search-field">'+icon('search')+'<input id="event-search" type="search" placeholder="Search events" aria-label="Search events" value="'+esc(eventSearch)+'"></label><label class="select-label">Category<select id="event-category">'+['All',...Object.keys(GROUPS)].map(t=>'<option '+(eventFilter===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><div class="event-catalog" id="event-results">'+eventCards()+'</div><p class="catalog-note">Catalog based on <a href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">HOSA’s 2026–27 guidelines</a>. Additional recognition and academic testing programs are separate from the annual competitive-event selection. State availability and eligibility may vary; check with your advisor.</p></main>'+footer();}
function startPage(){return siteHeader()+'<main id="main" class="start-page"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Your next chapter<br><em>starts here.</em></h1><p>Take a look inside Halus. Choose a demo view to explore.</p><div class="role-cards"><a href="#/student">'+icon('book')+'<h2>I’m a student</h2><p>Find your focus, practice, and connect with your chapter.</p><span>Enter student preview '+icon('arrow')+'</span></a><a href="#/teacher">'+icon('users')+'<h2>I’m an instructor</h2><p>Guide your students and keep your chapter moving forward.</p><span>Enter instructor preview '+icon('arrow')+'</span></a></div><small>This local preview uses sample data saved in your browser. No account is required.</small>'+hal()+'</main>';}
function missionPage(){const pillars=[['Free, always','Every lesson, practice set, and study tool for students is free. No premium tier, no paywall between you and your event.','lock'],['Built for one event','HOSA students compete in one event a year. Halus is shaped around that single focus instead of spreading you thin.','book'],['For every chapter','Instructors get assignments, analytics, and a private chapter space at no cost, so any school can take part.','users']];
 return siteHeader('mission')+'<main id="main" class="landing mission"><section class="mission-hero"><div class="aurora" aria-hidden="true"><i></i><i></i><i></i><i></i></div>'+backgroundPaths(12)+'<div class="mission-copy" data-reveal><span class="eyebrow glass-chip"><i></i> WHAT IS HALUS?</span><h1>Free prep for<br><em>every HOSA student.</em></h1><p>Halus is a study space for high school students competing in HOSA–Future Health Professionals. Our mission is simple: support every competitor, wherever they’re from, at no cost.</p></div><div class="mission-badge glass-card" data-reveal style="--d:.15s">'+hal()+'<strong>$0</strong><span class="micro">FOR STUDENTS. FOR INSTRUCTORS. FOR GOOD.</span></div></section>'+
 '<section class="mission-pillars">'+pillars.map((p,i)=>'<article class="spotlight glass-card" data-reveal style="--d:'+(i*.1)+'s"><span class="pillar-icon">'+icon(p[2])+'</span><span class="micro">0'+(i+1)+'</span><h3>'+p[0]+'</h3><p>'+p[1]+'</p></article>').join('')+'</section>'+
 '<section class="mission-why" data-reveal><span class="eyebrow">WHY IT MATTERS</span><h2>Talent is everywhere.<br><em>Resources aren’t.</em></h2><p>Some chapters have years of study materials and experienced advisors. Others are starting from scratch. Halus exists so that a student’s preparation depends on their effort, not their budget. Hal will be right there with you, one small step at a time.</p></section>'+
 '<section class="closing" data-reveal>'+backgroundPaths(10)+'<div><span class="eyebrow">JOIN FOR FREE</span><h2>Your event is waiting.</h2></div><div class="closing-actions">'+linkButton('Student login','#/student')+linkButton('Instructor login','#/teacher',true)+'</div></section>'+
 '<p class="mission-note">Halus is an independent project and is not affiliated with or endorsed by HOSA–Future Health Professionals. This is a local preview; accounts are not connected yet.</p></main>'+footer();}
function leaderboardPage(){return siteHeader('rankings')+'<main id="main" class="landing public-ranks">'+rankings()+'</main>'+footer();}
const PUBLIC=['/','/about','/instructors','/events','/start','/mission','/leaderboard'];
let stopLanding=null;
function render(){stopLanding?.();stopLanding=null;const route=location.hash.slice(1)||'/';document.title='Halus — '+({'/':'Your future, in practice.','/mission':'What is Halus?','/leaderboard':'Global rankings','/events':'Explore events','/start':'Step inside'}[route]||'Your study space');document.body.classList.toggle('in-workspace',!PUBLIC.includes(route));if(route==='/student'){state.role='student';save();}if(route==='/teacher'){state.role='teacher';save();}
 let content,page='overview';
 if(['/','/about','/instructors'].includes(route)){app.innerHTML=landing();stopLanding=initLanding(app);if(route!=='/')requestAnimationFrame(()=>document.getElementById(route.slice(1))?.scrollIntoView({behavior:'smooth'}));return;}
 const pages={'/start':startPage,'/events':eventsPage,'/mission':missionPage,'/leaderboard':leaderboardPage};
 if(pages[route]){app.innerHTML=pages[route]();stopLanding=initLanding(app);return;}
 switch(route){case '/student': content=overview();break;case '/teacher':content=teacherOverview();break;case '/my-event':content=myEvent();page='event';break;case '/students':content=studentsPage();page='students';break;case '/assignments':content=assignmentsPage();page='assignments';break;case '/analytics':content=analytics();page='analytics';break;case '/community':content=community();page='community';break;case '/rankings':content=rankings();page='rankings';break;default:location.hash='/';return;}
 app.innerHTML=shell(content,page);
}
function lessonModal(id){const l=LESSONS.find(x=>x.id===id);if(!l)return;showModal(l.title,'<span class="eyebrow">STARTER LESSON · '+l.time+'</span><p class="lesson-body">'+l.body+'</p><a class="resource-link" href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">'+icon('book')+' Open official HOSA guidelines ↗</a><div class="callout"><strong>A small step to try</strong><p>Write one thing you want to prepare this week in your event notebook.</p></div><div class="modal-actions">'+button(state.completed.includes(id)?'Completed':'Mark as complete','complete-lesson','data-id="'+id+'"')+'</div>');}
function assignmentModal(id){const a=state.assignments.find(x=>x.id===id);if(!a)return;showModal(esc(a.title),'<span class="eyebrow">'+esc(a.type)+' · DUE '+date(a.due)+'</span><p class="lesson-body">'+esc(a.instructions||'Review this assignment with your instructor.')+'</p>'+(state.role==='teacher'?'<div class="callout"><strong>'+esc(a.event)+'</strong><p>'+(a.submitted?'Maya submitted a response:':'No submission in this preview yet.')+'</p>'+(a.response?'<p>'+esc(a.response)+'</p>':'')+'</div>':a.submitted?'<div class="callout"><strong>Submitted. Nice work.</strong><p>'+esc(a.response)+'</p></div>':'<form id="submit-assignment" data-id="'+id+'"><label class="field">Your response<textarea name="response" rows="5" required maxlength="5000" placeholder="Share your reflection or practice notes…"></textarea></label><button class="button" type="submit">Submit assignment</button></form>'));}
function createAssignmentModal(){showModal('Give your chapter a next step.','<form id="create-assignment"><label class="field">Assignment title<input name="title" maxlength="120" required placeholder="e.g. Review your event guidelines"></label><div class="form-grid"><label class="field">Event group<select name="event">'+EVENTS.map(e=>'<option '+(e.name===state.event?'selected':'')+'>'+esc(e.name)+'</option>').join('')+'</select></label><label class="field">Assignment type<select name="type"><option>Lesson</option><option>Quiz</option><option>Skill checklist</option><option>Reflection</option></select></label></div><label class="field">Due date<input type="date" name="due" required min="'+new Date().toLocaleDateString('en-CA')+'"></label><label class="field">Instructions<textarea name="instructions" rows="4" maxlength="5000" required placeholder="What should students work on?"></textarea></label><p class="subtle">Saved to the matching event group in this browser’s demo chapter.</p><button class="button" type="submit">Create assignment</button></form>');}
let quizIndex=0,quizAnswers=[];
function quizModal(){const q=LESSONS[quizIndex];showModal('A quick check-in.','<span class="eyebrow">QUESTION '+(quizIndex+1)+' OF '+LESSONS.length+'</span><h3 class="quiz-question">'+q.question+'</h3><form id="quiz-answer"><div class="quiz-options">'+q.options.map((o,i)=>'<label><input type="radio" name="answer" value="'+i+'" required><span>'+esc(o)+'</span></label>').join('')+'</div><button type="submit" class="button">Check answer</button></form>');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('halus-theme',document.documentElement.dataset.theme);}catch{}document.querySelectorAll('.theme-toggle').forEach(b=>{b.outerHTML=themeButton();});return;}
 if(action==='close'){modal.close();return;}
 if(action==='enter'){location.hash='/start';return;}
 if(action==='menu'){document.querySelector('.sidebar').classList.toggle('open');return;}
 if(action==='switch-role'){location.hash=state.role==='teacher'?'/student':'/teacher';return;}
 if(action==='about'){showModal('A first look at Halus.','<p class="lesson-body">This is a working local design preview. Assignments, posts, notes, and learning activity are saved only in this browser. The instructor/student switch is for exploring the design—not real authentication.</p><p>Real accounts, server-enforced school privacy, full event curriculum, uploads, and ranked assessment are not connected yet.</p><p>HOSA event references: <a href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">2026–27 guidelines ↗</a></p>');return;}
 if(action==='lesson'){lessonModal(el.dataset.id);return;}
 if(action==='complete-lesson'){state=completeLesson(state,el.dataset.id);save();modal.close();render();toast('Lesson complete. One small step forward.');return;}
 if(action==='assignment'){assignmentModal(el.dataset.id);return;}
 if(action==='create-assignment'){createAssignmentModal();return;}
 if(action==='filter-assignment'){assignmentFilter=el.dataset.value;render();return;}
 if(action==='event-tab'){currentTab=el.dataset.value;render();return;}
 if(action==='rank-scope'){rankScope=el.dataset.value;render();return;}
 if(action==='save-notes'){state.notes=document.querySelector('#event-notes').value;save();toast('Your notes are saved.');return;}
 if(action==='quiz'){quizIndex=0;quizAnswers=[];quizModal();return;}
 if(action==='quiz-next'){quizIndex++;if(quizIndex<LESSONS.length){quizModal();}else{const score=Math.round(quizAnswers.filter(Boolean).length/LESSONS.length*100);state.quizHistory.push({score,date:new Date().toISOString()});save();showModal('A little more prepared.','<div class="quiz-result">'+ring(score)+'<h3>'+quizAnswers.filter(Boolean).length+' of '+LESSONS.length+' correct</h3><p>Review any missed topics, then keep going at your own pace.</p><p class="subtle">Orientation practice does not award rank points.</p>'+button('Back to my event','close')+'</div>');render();}return;}
 if(action==='announce'){location.hash='/community';setTimeout(()=>document.querySelector('#post-text')?.focus(),50);return;}
 if(action==='change-school'){showModal('Explore a demo chapter.','<p>Switching chapters changes the visible demo feed. This is not real school membership or access control.</p><form id="change-school"><label class="field">Demo school<select name="school">'+Object.entries(SCHOOLS).map(([id,n])=>'<option value="'+id+'" '+(state.school===id?'selected':'')+'>'+n+'</option>').join('')+'</select></label><button class="button" type="submit">Open chapter</button></form>');return;}
 if(action==='manage-event'){showModal('Manage Maya’s annual event.','<p>Changing this event replaces the annual selection and resets her starter progress, practice history, skills checklist, and notes. Existing assignments stay with their original event group.</p><form id="manage-event"><label class="field">Annual event<select name="event">'+EVENTS.map(e=>'<option '+(e.name===state.event?'selected':'')+'>'+esc(e.name)+'</option>').join('')+'</select></label><button class="button" type="submit">Save annual event</button></form>');return;}
 if(action==='event-detail'){const ev=EVENTS.find(x=>x.name===el.dataset.event);showModal(esc(ev.name),'<span class="eyebrow">'+ev.category+' / SECONDARY</span><p class="lesson-body">Explore the official requirements, references, and preparation format for '+esc(ev.name)+'. '+(ev.special?'This event has additional IDEA eligibility requirements. ':'')+'Your advisor can help confirm state availability and eligibility.</p><a class="resource-link" href="https://hosa.org/guidelines" target="_blank" rel="noreferrer">Read official guidelines ↗</a><p class="subtle">'+(state.event?'Your current annual event is '+esc(state.event)+'. An instructor can change your selection.':'Choose one event to focus on this year.')+'</p>'+button(state.event===ev.name?'Open my event':state.event?'Explore student preview':'Choose this event',state.event?'open-event':'select-event','data-event="'+esc(ev.name)+'"'));return;}
 if(action==='open-event'){modal.close();state.role='student';save();location.hash='/my-event';return;}
 if(action==='select-event'){try{state=selectEvent(state,el.dataset.event);save();modal.close();location.hash='/student';}catch(err){toast(err.message);}return;}
});
document.addEventListener('submit',e=>{const form=e.target;if(!['post-form','create-assignment','submit-assignment','quiz-answer','change-school','manage-event'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));try{
 if(form.id==='post-form'){state=addPost(state,data.text);save();render();toast('Posted to your demo chapter.');}
 if(form.id==='create-assignment'){state=createAssignment(state,data);save();modal.close();render();toast('Assignment created for '+data.event+'.');}
 if(form.id==='submit-assignment'){const a=state.assignments.find(x=>x.id===form.dataset.id);if(!data.response.trim())throw new Error('Write a response first.');a.response=data.response.trim();a.submitted=true;save();modal.close();render();toast('Assignment submitted.');}
 if(form.id==='quiz-answer'){const q=LESSONS[quizIndex],correct=Number(data.answer)===q.answer;quizAnswers.push(correct);showModal(correct?'You’ve got it.':'A chance to learn.','<div class="quiz-feedback">'+icon(correct?'check':'book')+'<p>'+q.explanation+'</p>'+button(quizIndex===LESSONS.length-1?'See my result':'Next question','quiz-next')+'</div>');}
 if(form.id==='change-school'){if(!SCHOOLS[data.school])throw new Error('Choose a valid demo chapter.');state.school=data.school;save();modal.close();render();}
 if(form.id==='manage-event'){if(data.event!==state.event){state=selectEvent({...state,event:null,completed:[],skills:[],quizHistory:[],notes:''},data.event);save();}modal.close();render();toast('Annual event saved.');}
 }catch(err){toast(err.message);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-skill]')){const i=Number(e.target.dataset.skill);state.skills=e.target.checked?[...new Set([...state.skills,i])]:state.skills.filter(x=>x!==i);save();}if(e.target.id==='event-category'){eventFilter=e.target.value;document.querySelector('#event-results').innerHTML=eventCards();}});
document.addEventListener('input',e=>{if(e.target.id==='event-search'){eventSearch=e.target.value;document.querySelector('#event-results').innerHTML=eventCards();}if(e.target.id==='student-search'){studentSearch=e.target.value;document.querySelector('#roster-result').innerHTML=roster();}});
window.addEventListener('hashchange',()=>{modal.close();assignmentFilter='All';render();if(!['#/about','#/instructors'].includes(location.hash))window.scrollTo({top:0,behavior:'instant'});});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();
